/**
 * Libron Bold, the face the share card is drawn in, as base64.
 *
 * ## Why a string and not a file
 *
 * Convex bundles functions and their imports; it does not ship arbitrary
 * assets, and there is no filesystem in the runtime to read one from. A
 * `readFileSync` here works locally and fails on deploy, which is the worst
 * shape of failure available. Base64 in a module is the only form guaranteed to
 * arrive.
 *
 * ## It replaced Instrument Sans, because the app stopped using it
 *
 * On 2026-10-11 the owner moved every surface that was set in Instrument Sans
 * to Libron, and a card drawn in a face the product no longer sets anywhere is
 * a card that looks like a different company's. (Instrument Sans had replaced
 * Onest here for the same reason.)
 *
 * **One face, one weight, and the card's mono is drawn in it too.** The kind
 * chip and the domain line wanted JetBrains Mono, which is a second binary and
 * a second glyph-coverage surface for two short Latin strings this file draws
 * perfectly well letterspaced. `cardCoverage.ts` reads the cmap of whatever
 * font it is handed, so one bundled face is one question about tofu rather
 * than two. Libron ships Regular and Bold only; the card's 600 is drawn in the
 * Bold.
 *
 * ## One line, on purpose
 *
 * The base64 is a single string literal: wrapped at 100 columns it is three
 * thousand lines of nothing anyone reads, and `pnpm architecture` counts
 * lines.
 *
 * ## The digest is aimed at this string, not at a file somewhere
 *
 * `CARD_FONT_SHA256` is the digest of the `.ttf` this base64 was generated
 * from, so a hand-edited or truncated string makes the header a lie.
 * `__tests__/cardArt.test.ts` hashes the DECODED bytes and compares.
 *
 * Source: `Libron-Bold.ttf` from the official v0.31 release `Libron.zip`
 * (github.com/nicoverbruggen/libron), unmodified. Libron (c) 2026 Nico
 * Verbruggen, SIL Open Font License 1.1 with Reserved Font Name "Libron"; the
 * licence text ships beside the web files as `apps/mobile/public/Libron-OFL.txt`.
 * SHA-256 of the source file: e5d2872bc8c40bd751b1deb354314c5151360fccdd953882d12bd0b8294ae2f4
 */

export const CARD_FONT_SHA256 =
  "e5d2872bc8c40bd751b1deb354314c5151360fccdd953882d12bd0b8294ae2f4";

/** The family name every satori tree and font registration uses. */
export const CARD_FONT_FAMILY = "Libron";

export const LIBRON_BOLD_BASE64 =
  "";

let decoded: Uint8Array | undefined;

/** The decoded font, memoised — satori wants an ArrayBuffer-ish per render. */
export function cardFont(): Uint8Array {
  decoded ??= Uint8Array.from(atob(LIBRON_BOLD_BASE64), (c) => c.charCodeAt(0));
  return decoded;
}
